+    // The three git probes run with their exact argv + cwd scoping.
+    expect(execMock).toHaveBeenCalledWith('git', ['rev-parse', '--show-toplevel'], { cwd: '/repo' });
+    expect(execMock).toHaveBeenCalledWith(
+      'git',
+      ['ls-files', '--full-name', '--', 'Cargo.toml'],
+      { cwd: '/repo' },
